    {
      "id": "step11",
      "title": "Chứng minh tam giác AHE đồng dạng với tam giác AHC",
      "explanation": "Tương tự, xét tam giác $AHE$ và tam giác $AHC$. Chúng vuông ($\\angle AEH = \\angle AHC = 90^\\circ$) và có chung góc $\\angle CAE = \\angle HAC$. Vậy $\\triangle AHE \\sim \\triangle AHC$ (g-g).",
      "math": "\\triangle AHE \\sim \\triangle AHC",
      "reason": "Hai góc tương ứng bằng nhau",
      "geometryActions": [
        {"action": "highlight", "targets": ["ang_AEH", "ang_AHC", "ang_HAC"]}
      ]
    },
    {
      "id": "step12",
      "title": "Viết hệ thức từ đồng dạng AHE và AHC",
      "explanation": "Từ $\\triangle AHE \\sim \\triangle AHC$, ta có $\\frac{AE}{AH} = \\frac{AH}{AC}$. Nhân chéo ta được $AE \\cdot AC = AH^2$.",
      "math": "\\frac{AE}{AH} = \\frac{AH}{AC} \\Rightarrow AE \\cdot AC = AH^2",
      "reason": "Tỉ số đồng dạng",
      "geometryActions": [
        {"action": "highlight", "targets": ["seg_AE", "seg_AH", "seg_AC"]}
      ]
    },
    {
      "id": "step13",
      "title": "Kết luận",
      "explanation": "Vì $AD \\cdot AB = AH^2$ và $AE \\cdot AC = AH^2$, nên $AD \\cdot AB = AE \\cdot AC$. Đpcm.",
      "math": "AD \\cdot AB = AH^2 = AE \\cdot AC \\Rightarrow AD \\cdot AB = AE \\cdot AC",
      "reason": "Thay thế",
      "geometryActions": [
        {"action": "highlight", "targets": ["seg_AD", "seg_AB", "seg_AE", "seg_AC"]}
      ]
    }
  ],
  "finalAnswer": {
    "text": "Vậy $AD \\cdot AB = AE \\cdot AC$.",
    "math": "AD \\cdot AB = AE \\cdot AC"
  },
